const fireArcherSheet=new Image();fireArcherSheet.assetSrc='assets/fire-archer-v1.png';let fireArrows=[];
function beginFireArcher(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=p.x-e.x-(p.y-e.y)<0?-1:1;e.attack={pattern:'fireBurningVolley',bespoke:true,windup:1,origin:{x:e.x,y:e.y},targets:[-110,0,110].map(offset=>({x:p.x-Math.sin(angle)*offset,y:p.y+Math.cos(angle)*offset})).filter(target=>lineClear(e,target)),fired:false};}
function fireArrowContains(arrow){return arrow.targets.some(target=>dist(p,target)<=60+1e-8&&lineClear(target,p));}
function stepFireArrow(arrow,dt){arrow.age=Math.round((arrow.age+dt)*1e6)/1e6;if(!arrow.hit&&arrow.age>=.4){arrow.targets=arrow.targets.filter(target=>lineClear(arrow.origin,target));if(!arrow.targets.length)return false;arrow.hit=true;if(fireArrowContains(arrow))hurt(48);playSound('fire',arrow.targets[0].x,arrow.targets[0].y);}while(!dead&&arrow.waves<4&&arrow.age>=Math.round((.95+arrow.waves*.55)*1e6)/1e6){arrow.waves++;if(fireArrowContains(arrow))hurt(24);}return arrow.age<2.85;}
function advanceFireArrows(dt,skipFresh=false){if(!started||paused||dead||!Number.isFinite(dt)||dt<=0)return;fireArrows=fireArrows.filter(a=>a.owner===p&&(skipFresh&&a.spawnClock===clock||stepFireArrow(a,dt)));}
const fireArcherAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r7e3')return fireArcherAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='fireBurningVolley'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=440&&clear){beginFireArcher(e);return;}e.state='idle';if(d>800&&!e.aware||d<=300&&clear)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,90*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,16)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.4;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;if(!a.fired&&e.elapsed>=1){a.fired=true;e.struck=true;let targets=a.targets.filter(target=>lineClear(a.origin,target));if(targets.length){let arrow={owner:p,origin:{...a.origin},targets:targets.map(target=>({...target})),age:0,hit:false,waves:0,spawnClock:clock};if(stepFireArrow(arrow,e.elapsed-1))fireArrows.push(arrow);}playSound('arrow',e.x,e.y);}if(e.elapsed>=1.6){e.attack=null;e.state='idle';e.t=3.2;}
};
const fireArcherUpdateBase=update;update=dt=>{let active=started&&!paused&&!dead;fireArcherUpdateBase(dt);if(active)advanceFireArrows(dt,true);};
const fireArcherResetBase=resetWorld;resetWorld=()=>{fireArrows=[];return fireArcherResetBase();};
const fireArcherLoadBase=loadWorld;loadWorld=(...args)=>{fireArrows=[];return fireArcherLoadBase(...args);};
const fireArcherDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r7e3'||!fireArcherSheet.complete||!fireArcherSheet.naturalWidth||!fireArcherSheet.naturalHeight)return fireArcherDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='fireBurningVolley')f={row:2,col:e.elapsed<.4?0:e.elapsed<1?1:e.elapsed<1.2?2:3};let q=project(e.x,e.y),sw=fireArcherSheet.naturalWidth/4,sh=fireArcherSheet.naturalHeight/3,w=230,h=w*sh/sw,anchor=.92;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,fireArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(fireArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const fireArcherSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r7e3'?140:fireArcherSizeBase(e);

function drawFireArrowPool(target,burning,age=0){let q=project(target.x,target.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=burning?'#ed652d55':'#e4a67518';ctx.strokeStyle=burning?'#ffc175':'#e4a675';ctx.lineWidth=burning?2:1;ctx.beginPath();ctx.arc(0,0,60,0,Math.PI*2);ctx.fill();ctx.stroke();if(burning){ctx.strokeStyle='#ffd48b';for(let i=0;i<5;i++){let angle=i*Math.PI*2/5+age*.4,x=Math.cos(angle)*32,y=Math.sin(angle)*32;ctx.beginPath();ctx.moveTo(x-5,y+8);ctx.lineTo(x,y-8-Math.sin(age*7+i)*4);ctx.lineTo(x+4,y+4);ctx.stroke();}}ctx.restore();}
const fireArcherGroundBase=drawGroundEffects;drawGroundEffects=()=>{fireArcherGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r7e3'):enemies)){let a=e.attack;if(e.species==='r7e3'&&e.hp>0&&a?.pattern==='fireBurningVolley'&&!a.fired)for(let target of a.targets)if(visibleAt(target.x,target.y))drawFireArrowPool(target,false);}for(let a of fireArrows){if(a.owner!==p)continue;for(let target of a.targets)if(visibleAt(target.x,target.y))drawFireArrowPool(target,a.hit,a.age);}};
const fireArcherEffectsBase=drawEffects;drawEffects=()=>{fireArcherEffectsBase();ctx.save();ctx.strokeStyle='#ffb66f';ctx.lineWidth=3;for(let a of fireArrows){if(a.owner!==p||a.age>=.4)continue;for(let target of a.targets){if(!visibleAt(target.x,target.y))continue;let t=a.age/.4,q=project(a.origin.x+(target.x-a.origin.x)*t,a.origin.y+(target.y-a.origin.y)*t);q.y-=Math.sin(t*Math.PI)*70+20*(1-t);ctx.beginPath();ctx.moveTo(q.x-8,q.y-16);ctx.lineTo(q.x,q.y);ctx.stroke();}}ctx.restore();};
